'use strict';
const C=window.BERSERK_ARCHIVE,M=window.ArchiveModel,$=id=>document.getElementById(id);
const storageKey='berserk-color-archive-progress-v2';
let saved=null;try{saved=localStorage.getItem(storageKey);}catch{}
let progress=M.safeProgress(saved),tab='chapters',pageSize=24,query='',year='all',pendingReveal=null;
const openGroups=new Set(),openVolumes=new Set([1,2,3,4,5]);
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function link(label,url){const a=node('a',label);a.href=url;if(/^https:/.test(url)){a.target='_blank';a.rel='noopener noreferrer';}return a;}
function button(text,fn,cls='reveal'){const b=node('button',text,cls);b.type='button';b.onclick=fn;return b;}
const chapterIndex=new Map();
for(let n=1;n<=3;n++)chapterIndex.set('prologue-'+n,{key:'prologue-'+n,order:n,volume:1,label:['Il guerriero nero','Il marchio','Gli angeli custodi dei desideri (1)'][n-1]});
for(let n=2;n<=16;n++)chapterIndex.set('revenge-'+n,{key:'revenge-'+n,order:n+3,volume:n<=5?2:n<=9?3:n<=14?4:5,label:n>=9?`L’età dell’oro (${n-8})`:`REVENGE ${n}`});
for(const e of C.entries)if(e.chapter)chapterIndex.set(e.chapter.key,e.chapter);
const sortedChapters=[...chapterIndex.values()].sort((a,b)=>a.order-b.order);
const progressChapters=[...new Map([...sortedChapters,...(C.progressChapters||[])].map(ch=>[ch.key,ch])).values()].sort((a,b)=>a.order-b.order);
const introNames={chapters:['LA TUA BERSERK COLLECTION','I colori tra le pagine.','Raggruppati per volume e capitolo. Prologue e REVENGE conservano la numerazione della pubblicazione originale; non tutti i capitoli hanno tavole a colori.'],extras:['OLTRE I CAPITOLI','Un’altra storia, a colori.','Copertine, poster, illustrazioni e scansioni, in ordine cronologico. Ogni materiale è protetto: la data non esclude spoiler.'],other:['DALLE GALLERIE DI FROSTI','Le altre opere.','Materiali di altri lavori presenti nell’archivio, separati da Berserk e ordinati per data.'],missing:['TRASPARENZA DELL’ARCHIVIO','Quello che manca.','File segnalati come mancanti nella fonte e download non riusciti. Nessun ripiego automatico su immagini online.']};
function updateBookmark(){const ch=progressChapters.find(c=>c.order===progress);$('bookmark').textContent=progress===19?'L’età dell’oro 8':ch?.label||'Non ho ancora iniziato';$('bookmark-volume').textContent=ch?.volume?`Berserk Collection · Volume ${ch.volume}`:'Il tuo percorso in Berserk';}
function stats(){const assets=Object.values(C.assets),ok=assets.filter(a=>a.status==='downloaded');$('stat-files').textContent=ok.length.toLocaleString('it-IT');$('stat-chapters').textContent=new Set(C.entries.filter(e=>e.section==='chapters').map(e=>e.chapter.key)).size;$('stat-size').textContent=(ok.reduce((s,a)=>s+(a.bytes||0),0)/1024**3).toLocaleString('it-IT',{maximumFractionDigits:2})+' GB';$('stat-missing').textContent=C.missingSourceFiles.length+assets.filter(a=>a.status==='failed').length;}
let viewerItems=[],viewerIndex=0;
function viewItems(entries){return [...new Set(entries.flatMap(e=>e.assetIds))].map(id=>({asset:C.assets[id],entry:entries.find(e=>e.assetIds.includes(id))})).filter(x=>x.asset.status==='downloaded');}
function showViewer(entries,index){viewerItems=viewItems(entries);viewerIndex=index;if(!viewerItems.length)return;renderViewer();$('viewer').showModal();}
function renderViewer(){const {asset:a,entry:e}=viewerItems[viewerIndex];$('viewer-chapter').textContent=e.chapter?.label||'Illustrazione extra';$('viewer-counter').textContent=`Tavola ${viewerIndex+1} di ${viewerItems.length}`;const img=node('img');img.src=M.localAssetPath(a.path);img.alt=`Tavola ${viewerIndex+1} · ${e.chapter?.label||'Illustrazione'}`;img.decoding='async';$('viewer-image').replaceChildren(img);$('viewer-caption').textContent=`${a.width} × ${a.height} px · ${(a.bytes/1024/1024).toFixed(2)} MB`;const links=$('viewer-links');links.replaceChildren(link('Apri immagine locale ↗',M.localAssetPath(a.path)),document.createTextNode(' · '),link('Originale e crediti ↗',a.filePageUrl));if(e.alternativeVersions?.length){const d=node('details');d.append(node('summary',`Altre versioni (${e.alternativeVersions.length}) · fonti esterne`));for(const v of e.alternativeVersions){const p=node('p');p.append(link(v.originalName+' ↗',v.filePageUrl));d.append(p);}links.append(d);}$('viewer-prev').disabled=viewerIndex===0;$('viewer-next').disabled=viewerIndex===viewerItems.length-1;}
function imageGrid(entries){const wrap=node('div',undefined,'image-grid'),items=viewItems(entries);for(const [index,{asset:a,entry:e}]of items.entries()){const fig=node('figure',undefined,'image-card'),caption=node('figcaption'),b=button('',()=>showViewer(entries,index),'image-open');b.setAttribute('aria-label',`Apri tavola ${index+1} nel viewer`);const img=node('img');img.src=M.localAssetPath(a.path);img.alt=`Tavola ${index+1} · ${e.chapter?.label||'Illustrazione'}`;img.loading='lazy';img.decoding='async';img.width=a.width;img.height=a.height;img.addEventListener('error',()=>{img.replaceWith(node('p','File locale non disponibile. Consulta il rapporto dei download.'));});b.append(img);fig.append(b);caption.append(button(`Tavola ${index+1} · Apri nel viewer ↗`,()=>showViewer(entries,index),'text-button'));caption.append(node('p',`${a.width} × ${a.height} px · ${(a.bytes/1024/1024).toFixed(2)} MB`));caption.append(link('Fonte e originale ↗',a.filePageUrl));if(e.alternativeVersions?.length){const d=node('details');d.append(node('summary',`Altre versioni (${e.alternativeVersions.length})`));for(const v of e.alternativeVersions){const p=node('p');p.append(link(v.originalName+' ↗',v.filePageUrl));d.append(p);}caption.append(d);}fig.append(caption);wrap.append(fig);}return wrap;}
function sources(entries){const el=node('div',undefined,'source-details');for(const e of entries){const row=node('p',e.description+' · '+(e.date||'Data non indicata')+' · ');row.append(link('Fonte Frosti ↗',e.sourcePage));if(e.dateBasis)row.append(document.createTextNode(' · '+e.dateBasis));el.append(row);}return el;}
function requestReveal(key,locked){if(openGroups.has(key)){openGroups.delete(key);render();return;}if(locked){pendingReveal=key;$('spoiler-message').textContent=tab==='chapters'?'Questo capitolo è successivo al tuo segnalibro. Le immagini possono anticipare la storia.':'Gli extra possono mostrare personaggi ed eventi futuri, anche quando la data è precedente al tuo segnalibro.';$('spoiler-dialog').showModal();}else{openGroups.add(key);render();}}
function renderChapter(ch,entries){const key='chapter:'+ch.key,open=openGroups.has(key),locked=ch.order>progress,el=node('article',undefined,'chapter'),head=node('div',undefined,'chapter-head'),text=node('div');text.append(node('span',locked?'OLTRE IL SEGNALIBRO':'FINO AL TUO SEGNALIBRO','badge'+(locked?' locked':'')));text.append(node('h3',locked?`Capitolo ${ch.key.replace('episode-','').replace('revenge-','REVENGE ').replace('prologue-','Prologo ')}`:ch.label));text.append(node('p',`${ch.key} · ${[...new Set(entries.flatMap(e=>e.assetIds))].length} tavole`,'small'));head.append(text);if(entries.some(e=>e.assetIds.length)){const b=button(open?'Nascondi immagini':locked?'Apri con avviso spoiler':'Mostra immagini',()=>requestReveal(key,locked));b.setAttribute('aria-expanded',String(open));head.append(b);}el.append(head);if(!entries.length)el.append(node('p','Nessuna tavola a colori catalogata per questo capitolo nelle fonti consultate.','no-color'));else if(open){el.append(imageGrid(entries),sources(entries));}else if(!entries.some(e=>e.assetIds.length))el.append(node('p','La fonte segnala un file mancante. Consulta “Non disponibili”.','no-color'));return el;}
function chapters(){const entries=C.entries.filter(e=>e.section==='chapters'),volumes=new Map();let count=0;for(const ch of sortedChapters){let items=entries.filter(e=>e.chapter.key===ch.key);if($('only-read').checked&&ch.order>progress)continue;const fake={section:'chapters',chapter:ch,description:ch.label,date:''};if(query&&!M.searchable(fake,progress).includes(query)&&!items.some(e=>M.searchable(e,progress).includes(query)))continue;const v=ch.volume||999;if(!volumes.has(v))volumes.set(v,[]);volumes.get(v).push([ch,items]);count++;}const container=$('archive');for(const [v,groups] of [...volumes].sort((a,b)=>a[0]-b[0])){const d=node('details',undefined,'volume');d.open=openVolumes.has(v);d.addEventListener('toggle',()=>d.open?openVolumes.add(v):openVolumes.delete(v));const summary=node('summary'),title=node('span',undefined,'vol-name');title.append(node('span',v===999?'—':String(v).padStart(2,'0'),'vol-number'),document.createTextNode(v===999?'Volume non ancora assegnato':`Collection ${v}`));summary.append(title,node('span',`${groups.length} ${groups.length===1?'capitolo':'capitoli'} · immagini coperte fino all’apertura`,'vol-info'));const body=node('div',undefined,'volume-body');for(const [ch,items]of groups)body.append(renderChapter(ch,items));d.append(summary,body);container.append(d);}$('results').textContent=`${count} capitoli nel catalogo · titoli futuri protetti`;$('load-more').hidden=true;}
function extras(){const entries=C.entries.filter(e=>e.section===tab&&!e.duplicateInChronologicalGallery).filter(e=>(year==='all'||(e.sortDate?.slice(0,4)||'undated')===year)&&(!query||M.searchable(e,progress).includes(query))).sort(M.compareDates),list=node('div',undefined,'extra-list');for(const e of entries.slice(0,pageSize)){const key=e.id,open=openGroups.has(key),card=node('article',undefined,'extra-card'+(open?' open':'')),head=node('div',undefined,'extra-head');head.append(node('span',(e.date||'Data non documentata')+(e.dateApproximate&&e.date?' · data indicativa':''),'extra-date'));head.append(node('h3',open?e.description:'Illustrazione protetta'));head.append(node('p',`${e.assetIds.length} tavola · ${e.id}`,'badge'));const b=button(open?'Nascondi materiale':'Mostra con avviso spoiler',()=>requestReveal(key,true));b.setAttribute('aria-expanded',String(open));head.append(b);card.append(head);if(open)card.append(imageGrid([e]),sources([e]));list.append(card);}$('archive').append(list);$('results').textContent=`${entries.length} materiali · ordine dalla data più antica · i non datati sono in fondo`;$('load-more').hidden=entries.length<=pageSize;}
function missing(){const list=node('ul',undefined,'missing-list');for(const m of C.missingSourceFiles){const li=node('li','File assente nella fonte · ');li.append(link('Apri il riferimento ↗',m.sourcePage));const d=node('details'),s=node('summary','Mostra nome del file (possibili spoiler)');d.append(s,node('p',m.file));li.append(d);list.append(li);}for(const a of Object.values(C.assets).filter(a=>a.status==='failed')){const li=node('li','Download non riuscito · '),d=node('details');d.append(node('summary','Dettagli del file (possibili spoiler)'),node('p',a.originalName),node('p',a.error),link('Pagina fonte ↗',a.filePageUrl));li.append(d);list.append(li);}$('archive').append(list);$('results').textContent=`${list.children.length} segnalazioni`;if(!list.children.length)$('archive').append(node('p','Tutti i file sono disponibili.','empty'));$('load-more').hidden=true;}
function render(){const [k,t,d]=introNames[tab];$('section-kicker').textContent=k;$('section-title').textContent=t;$('section-description').textContent=d;$('archive').replaceChildren();$('read-label').hidden=tab!=='chapters';$('year-label').hidden=!['extras','other'].includes(tab);$('search').closest('label').hidden=tab==='missing';$('search').placeholder=tab==='chapters'?'Numero, volume o capitolo già letto…':'Cerca anno (titoli protetti dagli spoiler)…';for(const b of document.querySelectorAll('[data-tab]'))b.setAttribute('aria-pressed',String(b.dataset.tab===tab));if(tab==='chapters')chapters();else if(tab==='missing')missing();else extras();if(!$('archive').children.length)$('archive').append(node('p','Nessun materiale per questi filtri.','empty'));}
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{tab=b.dataset.tab;query='';year='all';pageSize=24;openGroups.clear();$('search').value='';$('year').value='all';render();};
$('search').oninput=e=>{query=e.target.value.trim().toLowerCase();pageSize=24;render();};$('only-read').onchange=render;$('year').onchange=e=>{year=e.target.value;pageSize=24;render();};$('load-more').onclick=()=>{pageSize+=24;render();};$('hide-all').onclick=()=>{openGroups.clear();render();};
for(const y of [...new Set(C.entries.map(e=>e.sortDate?.slice(0,4)).filter(Boolean))].sort())$('year').append(new Option(y,y));$('year').append(new Option('Non datati','undated'));
$('spoiler-dialog').addEventListener('close',()=>{if($('spoiler-dialog').returnValue==='reveal'&&pendingReveal)openGroups.add(pendingReveal);pendingReveal=null;$('spoiler-dialog').returnValue='cancel';render();});
$('edit-progress').onclick=()=>{$('progress-select').replaceChildren(new Option('Non ho ancora iniziato','0'));for(const ch of progressChapters)$('progress-select').append(new Option(`${ch.volume?'Collection '+ch.volume:'Non assegnato'} · ${ch.order<=19?ch.label:ch.key}`,ch.order));$('progress-select').value=String(progress);$('progress-dialog').showModal();};
$('progress-dialog').addEventListener('close',()=>{const action=$('progress-dialog').returnValue;if(action==='save'||action==='reset'){progress=action==='reset'?0:M.safeProgress($('progress-select').value);try{localStorage.setItem(storageKey,String(progress));}catch{}openGroups.clear();updateBookmark();render();}$('progress-dialog').returnValue='cancel';});
$('viewer-close').onclick=()=>$('viewer').close();
$('viewer-prev').onclick=()=>{if(viewerIndex>0){viewerIndex--;renderViewer();}};
$('viewer-next').onclick=()=>{if(viewerIndex<viewerItems.length-1){viewerIndex++;renderViewer();}};
$('viewer').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();$('viewer-prev').click();}if(e.key==='ArrowRight'){e.preventDefault();$('viewer-next').click();}});
$('viewer').addEventListener('close',()=>{$('viewer-image').replaceChildren();viewerItems=[];});
stats();updateBookmark();render();
